import { DatabaseSync, type StatementSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';
import type { Job, JobStatus, Submission } from './jobs.ts';

/** Row shape of the `jobs` table. Internal columns (seq, idempotency_key, ...) never leave this module. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  idempotency_key: string | null;
  payload_fingerprint: string | null;
  /** Epoch milliseconds before which a queued job must not be claimed (retry delay). */
  available_at: number;
}

export type CreateResult =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  idempotency_key TEXT UNIQUE,
  payload_fingerprint TEXT,
  available_at INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS heartbeat (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  at INTEGER NOT NULL
);
`;

/**
 * Opens the SQLite database shared by the server and worker processes and makes sure the schema
 * exists. Either process may call this first; the schema statements are idempotent.
 */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec('PRAGMA foreign_keys = ON;');
  runInTransaction(db, () => db.exec(SCHEMA));
  return db;
}

/** Runs `fn` inside BEGIN IMMEDIATE / COMMIT, rolling back on any failure. Never span an `await`. */
export function runInTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let committed = false;
  try {
    const value = fn();
    db.exec('COMMIT');
    committed = true;
    return value;
  } finally {
    if (!committed) {
      try {
        db.exec('ROLLBACK');
      } catch {
        // no transaction is active (e.g. the failure happened in COMMIT and already rolled back)
      }
    }
  }
}

/** Converts a stored row to the public job representation. */
export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

interface Statements {
  insertJob: StatementSync;
  jobById: StatementSync;
  jobByKey: StatementSync;
  listJobs: StatementSync;
  nextQueued: StatementSync;
  nextRunning: StatementSync;
  claim: StatementSync;
  resetProgress: StatementSync;
  setProgress: StatementSync;
  requeue: StatementSync;
  fail: StatementSync;
  complete: StatementSync;
  upsertHeartbeat: StatementSync;
  readHeartbeat: StatementSync;
}

/** Prepared statements and the state transitions used by the server and the worker. */
export class Store {
  readonly db: DatabaseSync;
  private readonly s: Statements;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.s = {
      insertJob: db.prepare(
        `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error,
                           created_at, updated_at, idempotency_key, payload_fingerprint, available_at)
         VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, ?, ?, ?, 0)`,
      ),
      jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
      jobByKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
      listJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
      nextQueued: db.prepare(
        `SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq ASC LIMIT 1`,
      ),
      nextRunning: db.prepare(`SELECT * FROM jobs WHERE status = 'running' ORDER BY seq ASC LIMIT 1`),
      claim: db.prepare(
        `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL,
                         updated_at = ?
         WHERE id = ? AND status = 'queued'`,
      ),
      resetProgress: db.prepare(
        `UPDATE jobs SET completed = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
      ),
      setProgress: db.prepare(
        `UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
      ),
      requeue: db.prepare(
        `UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      fail: db.prepare(
        `UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = ?, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      complete: db.prepare(
        `UPDATE jobs SET status = 'completed', completed = steps, output = ?, error = NULL, updated_at = ?
         WHERE id = ? AND status = 'running'`,
      ),
      upsertHeartbeat: db.prepare(
        `INSERT INTO heartbeat (id, at) VALUES (1, ?)
         ON CONFLICT (id) DO UPDATE SET at = excluded.at`,
      ),
      readHeartbeat: db.prepare('SELECT at FROM heartbeat WHERE id = 1'),
    };
  }

  close(): void {
    this.db.close();
  }

  transaction<T>(fn: () => T): T {
    return runInTransaction(this.db, fn);
  }

  // ---- server side -------------------------------------------------------------------------

  /** Creates a job, or returns the existing one for the same idempotency key. */
  createJob(sub: Submission, fingerprint: string, idempotencyKey: string | undefined, id: string = randomUUID()): CreateResult {
    return this.transaction<CreateResult>(() => {
      if (idempotencyKey !== undefined) {
        const existing = this.s.jobByKey.get(idempotencyKey) as unknown as JobRow | undefined;
        if (existing) {
          return existing.payload_fingerprint === fingerprint
            ? { kind: 'replayed', job: toJob(existing) }
            : { kind: 'conflict' };
        }
      }
      const now = new Date().toISOString();
      this.s.insertJob.run(id, sub.input, sub.steps, sub.failAttempts, now, now, idempotencyKey ?? null, fingerprint);
      const row = this.s.jobById.get(id) as unknown as JobRow;
      return { kind: 'created', job: toJob(row) };
    });
  }

  getJob(id: string): Job | undefined {
    const row = this.s.jobById.get(id) as unknown as JobRow | undefined;
    return row ? toJob(row) : undefined;
  }

  listJobs(): Job[] {
    return (this.s.listJobs.all() as unknown as JobRow[]).map(toJob);
  }

  /** Epoch milliseconds of the worker's last heartbeat, if any. */
  lastHeartbeat(): number | undefined {
    const row = this.s.readHeartbeat.get() as { at: number } | undefined;
    return row?.at;
  }

  // ---- worker side -------------------------------------------------------------------------

  recordHeartbeat(nowMs: number): void {
    this.s.upsertHeartbeat.run(nowMs);
  }

  /** A job left `running` by an earlier worker process, if any. */
  findRunning(): JobRow | undefined {
    return this.s.nextRunning.get() as unknown as JobRow | undefined;
  }

  /** Claims the oldest queued job whose retry delay has passed. Returns the claimed row. */
  claimNext(nowMs: number, nowIso: string): JobRow | undefined {
    return this.transaction(() => {
      const next = this.s.nextQueued.get(nowMs) as unknown as JobRow | undefined;
      if (!next) return undefined;
      this.s.claim.run(nowIso, next.id);
      return this.s.jobById.get(next.id) as unknown as JobRow;
    });
  }

  getRow(id: string): JobRow | undefined {
    return this.s.jobById.get(id) as unknown as JobRow | undefined;
  }

  resetProgress(id: string, nowIso: string): void {
    this.s.resetProgress.run(nowIso, id);
  }

  setProgress(id: string, completed: number, nowIso: string): void {
    this.s.setProgress.run(completed, nowIso, id);
  }

  requeue(id: string, availableAtMs: number, nowIso: string): void {
    this.s.requeue.run(availableAtMs, nowIso, id);
  }

  fail(id: string, error: string, nowIso: string): void {
    this.s.fail.run(error, nowIso, id);
  }

  complete(id: string, output: string, nowIso: string): void {
    this.s.complete.run(output, nowIso, id);
  }
}

