/** Shared job types and submission validation. No I/O happens here. */

export const JOB_STATUSES = ['queued', 'running', 'completed', 'failed'] as const;
export type JobStatus = (typeof JOB_STATUSES)[number];

/** Public job representation returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Payload after defaults have been applied. */
export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export type ValidationResult =
  | { ok: true; submission: Submission; idempotencyKey: string | undefined }
  | { ok: false; fields: FieldError[] };

export const MAX_BODY_BYTES = 64 * 1024;
export const MAX_INPUT_LENGTH = 1000;
export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;

const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

/** Fixed-order serialization of the normalized payload, used for idempotency comparisons. */
export function fingerprint(sub: Submission): string {
  return JSON.stringify([sub.input, sub.steps, sub.failAttempts]);
}

function isInteger(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

export interface RawSubmission {
  /** Value of the Content-Type header, if any. */
  contentType: string | undefined;
  /** Value of the Idempotency-Key header (already joined if repeated), if any. */
  idempotencyKeyHeader: string | undefined;
  /** Request body decoded as UTF-8, or null when it exceeded MAX_BODY_BYTES. */
  body: string | null;
}

/** Validates a POST /api/jobs request, reporting every offending field. */
export function validateSubmission(raw: RawSubmission): ValidationResult {
  const fields: FieldError[] = [];

  const mediaType = (raw.contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
  }

  let obj: Record<string, unknown> | undefined;
  if (raw.body === null) {
    fields.push({ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` });
  } else {
    let parsed: unknown;
    let parseFailed = false;
    try {
      parsed = JSON.parse(raw.body);
    } catch {
      parseFailed = true;
    }
    if (parseFailed) {
      fields.push({ field: 'body', message: 'Request body must be valid JSON.' });
    } else if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      fields.push({ field: 'body', message: 'Request body must be a JSON object.' });
    } else {
      obj = parsed as Record<string, unknown>;
    }
  }

  let submission: Submission | undefined;
  if (obj) {
    for (const key of Object.keys(obj)) {
      if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'Unknown field.' });
    }

    let input: string | undefined;
    if (!Object.prototype.hasOwnProperty.call(obj, 'input')) {
      fields.push({ field: 'input', message: 'input is required.' });
    } else if (typeof obj.input !== 'string') {
      fields.push({ field: 'input', message: 'input must be a string.' });
    } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
      fields.push({ field: 'input', message: `input must be 1 to ${MAX_INPUT_LENGTH} characters.` });
    } else if (obj.input.trim() === '') {
      fields.push({ field: 'input', message: 'input must not be only whitespace.' });
    } else {
      input = obj.input;
    }

    let steps: number | undefined;
    if (!Object.prototype.hasOwnProperty.call(obj, 'steps')) {
      steps = DEFAULT_STEPS;
    } else if (isInteger(obj.steps, 1, 20)) {
      steps = obj.steps;
    } else {
      fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20.' });
    }

    let failAttempts: number | undefined;
    if (!Object.prototype.hasOwnProperty.call(obj, 'failAttempts')) {
      failAttempts = DEFAULT_FAIL_ATTEMPTS;
    } else if (isInteger(obj.failAttempts, 0, 5)) {
      failAttempts = obj.failAttempts;
    } else {
      fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5.' });
    }

    if (input !== undefined && steps !== undefined && failAttempts !== undefined) {
      submission = { input, steps, failAttempts };
    }
  }

  if (raw.idempotencyKeyHeader !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(raw.idempotencyKeyHeader)) {
    fields.push({
      field: 'Idempotency-Key',
      message: 'Idempotency-Key must be 1 to 128 characters from A-Z, a-z, 0-9, "_" and "-".',
    });
  }

  if (fields.length > 0 || submission === undefined) {
    if (fields.length === 0) fields.push({ field: 'body', message: 'Request body is invalid.' });
    return { ok: false, fields };
  }
  return { ok: true, submission, idempotencyKey: raw.idempotencyKeyHeader };
}

