import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, Store } from './db.ts';
import { fingerprint, MAX_BODY_BYTES, validateSubmission } from './jobs.ts';

const HEARTBEAT_FRESH_MS = 3000;
const SHUTDOWN_DRAIN_MS = 3000;
const SHUTDOWN_HARD_MS = 5000;

const store = new Store(openDatabase());
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  const text = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(text),
    ...extraHeaders,
  });
  res.end(text);
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: { field: string; message: string }[],
  extraHeaders?: Record<string, string>,
): void {
  sendJson(res, status, { error: fields ? { code, message, fields } : { code, message } }, extraHeaders);
}

function notFound(res: ServerResponse): void {
  sendError(res, 404, 'not_found', 'No such route or resource.');
}

function methodNotAllowed(res: ServerResponse, allowed: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed; use ${allowed}.`, undefined, { allow: allowed });
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        chunks.length = 0;
        return;
      }
      if (!tooLarge) chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const idempotencyHeader = req.headers['idempotency-key'];
  const validation = validateSubmission({
    contentType: req.headers['content-type'],
    idempotencyKeyHeader: Array.isArray(idempotencyHeader) ? idempotencyHeader.join(', ') : idempotencyHeader,
    body,
  });
  if (!validation.ok) {
    sendError(res, 400, 'invalid_request', 'The job submission is invalid.', validation.fields);
    return;
  }
  const result = store.createJob(validation.submission, fingerprint(validation.submission), validation.idempotencyKey);
  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, result.kind === 'created' ? 201 : 200, result.job);
}

function health(res: ServerResponse): void {
  const beat = store.lastHeartbeat();
  const up = beat !== undefined && Date.now() - beat <= HEARTBEAT_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function parsePathname(rawUrl: string | undefined): string | undefined {
  try {
    return new URL(rawUrl ?? '/', 'http://localhost').pathname;
  } catch {
    return undefined;
  }
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const path = parsePathname(req.url);
  if (path === undefined) return notFound(res);

  if (path === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return health(res);
  }

  if (path === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'content-length': Buffer.byteLength(uiHtml) });
    res.end(uiHtml);
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return notFound(res);
    }
    const job = store.getJob(id);
    return job ? sendJson(res, 200, job) : notFound(res);
  }

  notFound(res);
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) {
      sendError(res, 500, 'internal_error', 'An unexpected error occurred.');
    } else {
      res.destroy();
    }
  });
});

let shuttingDown = false;
function shutdown(signal: string): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`server stopping on ${signal}`);
  const hardExit = setTimeout(() => {
    try {
