import { openDatabase, Store, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 100;
const RETRY_DELAY_MS = 500;
const HEARTBEAT_MS = 500;
const MAX_ATTEMPTS = 3;
const TRANSIENT_ERROR = 'transient failure';

let stopping = false;
let wakeSleeper: (() => void) | undefined;

function requestStop(signal: string): void {
  if (stopping) return;
  stopping = true;
  console.log(`worker stopping on ${signal}`);
  wakeSleeper?.();
}

/** Waits `ms`, or returns early when shutdown begins. */
function pause(ms: number): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(() => {
      wakeSleeper = undefined;
      resolve();
    }, ms);
    wakeSleeper = () => {
      clearTimeout(timer);
      wakeSleeper = undefined;
      resolve();
    };
  });
}

/**
 * Runs one attempt of a job that is already `running` in the database. Every state change is a
 * short transaction, and nothing is awaited while one is open.
 */
async function runAttempt(store: Store, job: JobRow): Promise<void> {
  await pause(STEP_MS);
  if (stopping) return;

  if (job.attempts <= job.fail_attempts) {
    const nowIso = new Date().toISOString();
    if (job.attempts < MAX_ATTEMPTS) {
      store.requeue(job.id, Date.now() + RETRY_DELAY_MS, nowIso);
      console.log(`job ${job.id} attempt ${job.attempts} failed transiently; retrying`);
    } else {
      store.fail(job.id, TRANSIENT_ERROR, nowIso);
      console.log(`job ${job.id} failed after ${job.attempts} attempts`);
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    if (step > 1) {
      await pause(STEP_MS);
      if (stopping) return;
    }
    const nowIso = new Date().toISOString();
    if (step < job.steps) {
      store.setProgress(job.id, step, nowIso);
    } else {
      // Final progress and completion commit together: the statement is a single atomic update.
      store.complete(job.id, job.input.toUpperCase(), nowIso);
      console.log(`job ${job.id} completed`);
    }
  }
}

async function main(): Promise<void> {
  const store = new Store(openDatabase());
  const beat = () => store.recordHeartbeat(Date.now());
  beat();
  const heartbeat = setInterval(() => {
    try {
      beat();
    } catch (err) {
      console.error('heartbeat failed:', err);
    }
  }, HEARTBEAT_MS);

  process.on('SIGTERM', () => requestStop('SIGTERM'));
  process.on('SIGINT', () => requestStop('SIGINT'));
  console.log('worker started');

  try {
    while (!stopping) {
      // Recovery first: a job still `running` was interrupted by an earlier worker process.
      // Its interrupted attempt keeps its number; its steps restart from zero.
      let job: JobRow | undefined = store.findRunning();
      if (job) {
        store.resetProgress(job.id, new Date().toISOString());
        job = store.getRow(job.id);
        console.log(`recovering job ${job?.id} attempt ${job?.attempts}`);
      } else {
        job = store.claimNext(Date.now(), new Date().toISOString());
        if (job) console.log(`job ${job.id} attempt ${job.attempts} started`);
      }

      if (!job) {
        await pause(POLL_MS);
        continue;
      }
      await runAttempt(store, job);
    }
  } finally {
    clearInterval(heartbeat);
    store.close();
  }
}

process.on('uncaughtException', (err) => {
  console.error('worker failed:', err);
  process.exit(1);
});

main().then(
  () => {
    console.log('worker stopped');
    process.exit(0);
  },
  (err: unknown) => {
    console.error('worker failed:', err);
    process.exit(1);
  },
);

